import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { paperAPI } from '../utils/api';
import { useAuth } from '../context/AuthContext';
import StatusBadge from '../components/StatusBadge';

export default function ScanRedirect() {
  const { id } = useParams();
  const nav = useNavigate();
  const { user, loading: authLoading } = useAuth();
  const [paper, setPaper]   = useState(null);
  const [loading, setLoading] = useState(true);
  const [marking, setMarking] = useState(false);
  const [done, setDone]     = useState('');
  const [error, setError]   = useState('');

  useEffect(() => {
    if (authLoading) return;
    if (!user) { nav(`/login?next=/scan/${id}`); return; }
    paperAPI.view(id)
      .then(r => setPaper(r.data.paper))
      .catch(() => setError('Paper not found.'))
      .finally(() => setLoading(false));
  }, [id, user, authLoading]);

  const mark = async (action) => {
    setMarking(true); setError('');
    try {
      await paperAPI.mark({
        paper_id: parseInt(id),
        action,
        dept_id: user.dept_id,
        note: 'qr-scan'
      });
      setDone(action);
      setPaper(p => ({ ...p, status_action: action, status_dept: user.dept_name }));
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to mark status.');
    } finally { setMarking(false); }
  };

  const canMark = user?.role === 'admin' || user?.dept_name === paper?.origin;

  if (authLoading || loading) return (
    <div style={styles.bg}>
      <div style={styles.card}>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <div className="spinner" style={{ margin: '0 auto' }} />
          <p style={{ marginTop: 12, color: '#888' }}>Loading paper...</p>
        </div>
      </div>
    </div>
  );

  if (error) return (
    <div style={styles.bg}>
      <div style={styles.card}>
        <div style={styles.header}>❌ Error</div>
        <div style={{ padding: 24, textAlign: 'center', color: '#b91c1c' }}>{error}</div>
        <div style={{ padding: '0 24px 24px', textAlign: 'center' }}>
          <button style={styles.btnOutline} onClick={() => nav('/dept')}>Go to Dashboard</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={styles.bg}>
      <div style={styles.card}>

        {/* Header */}
        <div style={styles.header}>
          <div style={styles.logo}>PTS</div>
          <div>
            <div style={{ fontWeight: 700, fontSize: 15, color: '#0d1b35' }}>Paper Tracking System</div>
            <div style={{ fontSize: 12, color: '#9aa0b8' }}>QR Scan — {user?.dept_name}</div>
          </div>
        </div>

        {/* Paper info */}
        <div style={{ padding: '20px 24px', borderBottom: '1px solid #eee' }}>
          <div style={styles.row}>
            <span style={styles.label}>REF</span>
            <span style={{ fontFamily: 'monospace', fontSize: 20, fontWeight: 800, color: '#0d1b35' }}>#{paper.ref_code}</span>
          </div>
          <div style={styles.row}>
            <span style={styles.label}>TITLE</span>
            <span style={{ fontWeight: 600 }}>{paper.title}</span>
          </div>
          <div style={styles.row}>
            <span style={styles.label}>ORIGIN</span>
            <span>{paper.origin}</span>
          </div>
          <div style={styles.row}>
            <span style={styles.label}>STATUS</span>
            <StatusBadge action={paper.status_action} dept={paper.status_dept} />
          </div>
        </div>

        {/* Action buttons */}
        <div style={{ padding: 24 }}>
          {done ? (
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 48, marginBottom: 8 }}>{done === 'IN' ? '✅' : done === 'OUT' ? '📤' : '🏁'}</div>
              <div style={{ fontWeight: 700, fontSize: 18, color: '#1a7f4e', marginBottom: 4 }}>
                Marked {done}!
              </div>
              <div style={{ fontSize: 13, color: '#888', marginBottom: 20 }}>Status updated successfully.</div>
              <button style={styles.btnOutline} onClick={() => nav(user?.role === 'admin' ? '/admin' : '/dept')}>
                ← Back to Dashboard
              </button>
            </div>
          ) : canMark ? (
            <div>
              <div style={{ fontSize: 13, fontWeight: 600, color: '#5a6480', marginBottom: 14, textAlign: 'center' }}>
                Update Status
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                <button style={styles.btnIN} onClick={() => mark('IN')} disabled={marking}>
                  ↓ Mark IN
                </button>
                <button style={styles.btnOUT} onClick={() => mark('OUT')} disabled={marking}>
                  ↑ Mark OUT
                </button>
                <button style={styles.btnDONE} onClick={() => mark('DONE')} disabled={marking}>
                  ✓ Mark Done
                </button>
              </div>
              <div style={{ marginTop: 16, textAlign: 'center' }}>
                <button style={styles.btnOutline} onClick={() => nav(`/paper/${id}`)}>
                  View Full Details
                </button>
              </div>
            </div>
          ) : (
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 13, color: '#888', marginBottom: 16 }}>
                Only <strong>{paper.origin}</strong> can update this paper's status.
              </div>
              <button style={styles.btnOutline} onClick={() => nav(`/paper/${id}`)}>
                View Details
              </button>
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

const styles = {
  bg: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #0d1b35 0%, #1a2f5a 100%)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    padding: 16,
  },
  card: {
    background: '#fff', borderRadius: 20,
    boxShadow: '0 20px 60px rgba(0,0,0,0.3)',
    width: '100%', maxWidth: 400,
    overflow: 'hidden',
  },
  header: {
    display: 'flex', alignItems: 'center', gap: 12,
    padding: '20px 24px', borderBottom: '1px solid #eee',
    background: '#f8f5ef',
  },
  logo: {
    width: 42, height: 42, borderRadius: '50%',
    background: '#0d1b35', border: '2px solid #c9a84c',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: 12, fontWeight: 800, color: '#c9a84c', letterSpacing: 1,
  },
  row: {
    display: 'flex', alignItems: 'center', gap: 12,
